SELECT AVG(omr.result_value) AS average_map FROM omr JOIN patients p ON omr.subject_id = p.subject_id JOIN admissions a ON p.subject_id = a.subject_id WHERE p.gender = 'F' AND p.anchor_age = 78 AND EXTRACT(YEAR FROM a.admittime) BETWEEN 2015 AND 2020 AND p.anchor_year_group IN (SELECT anchor_year_group FROM patients WHERE gender = 'F' AND anchor_age BETWEEN 73 AND 83) AND omr.result_name = 'MAP' AND omr.valueuom = 'mmHg';